{"cmd":"python - <<'PY'
import csv
rows=[]
with open('/app/benchmark/data.csv', newline='', encoding='utf-8') as f:
    for r in csv.DictReader(f):
        r['Year']=int(r['Year']); rows.append(r)
rows=sorted(rows, key=lambda r:r['Year'])

# look for consecutive-year same composer (streaks length>=2)
streaks=[]
cur=rows[0]
cur_c=cur['Composer']; start=cur['Year']; last=cur['Year']; length=1
for r in rows[1:]:
    if r['Composer']==cur_c and r['Year']==last+1:
        last=r['Year']; length+=1
    else:
        if length>=2:
            streaks.append((cur_c,start,last,length))
        cur_c=r['Composer']; start=r['Year']; last=r['Year']; length=1
if length>=2:
    streaks.append((cur_c,start,last,length))
print('streaks', streaks)
PY"}

