+        t.setAttribute('fill', opts.fill || 'rgba(233,236,245,0.85)');
+        t.setAttribute('font-size', opts.size || 11);
+        t.setAttribute('font-weight', opts.weight || 500);
+        t.setAttribute('font-family', opts.font || 'ui-sans-serif, system-ui');
+        t.textContent = text;
+        svg.appendChild(t);
